"""
Module providing the functionality to create the bip
collector configuration for cloud gNodeB deployment.
"""


class CloudBipCollectorConfigurator:

    def add_bip(self, ne_log_name, ne_log_configuration):
        vdu_collector_names = []

        for vdu_id in self.tl_config_information_provider.get_du_ids(node_id=self.ne_id):

            bip_collector_configuration = self._create_vdu_interface_mirroring_l1l2bip_collector_configuration(
                node_id=self.ne_id,
                vdu_id=vdu_id,
                ne_log_configuration=ne_log_configuration,
            )

            vdu_collector_names.append(bip_collector_configuration.get('name'))

        bip_group_collector = {
            'type': 'group',
            'name': f'{ne_log_name}',
            'members': vdu_collector_names
        }

        self._collector_configuration_data.append(bip_group_collector)

        self._collector_configuration_data.add_mapping_entry(
            log_type='bip',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=bip_group_collector)

    def _create_vdu_interface_mirroring_l1l2bip_collector_configuration(self, node_id, vdu_id, ne_log_configuration):

        webservice = self.tl_config_information_provider.get_vdu_oam_http_connection_details(
            node_id=node_id,
            vdu_id=vdu_id,
        )

        vdu_interface_mirroring_l1l2bip_collector = {
            'name': f'vdu_interface_mirroring_l1l2bip_collector_vdu_{vdu_id}',
            'webservice': webservice,
            'type': 'vdu_interface_mirroring_l1l2bip'}
        for key in ['nr_cell_dns', 'interface', 'remove_zip_file', 'timeout']:
            if key in ne_log_configuration:
                vdu_interface_mirroring_l1l2bip_collector[key] = ne_log_configuration[key]

        self._collector_configuration_data.append(vdu_interface_mirroring_l1l2bip_collector)

        return vdu_interface_mirroring_l1l2bip_collector
